package net.civeira.phylax.feature.identity.useracceptedtermsofuse.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenanttermsofuse.domain.TenantTermsOfUseReference;

class TermsOfUseVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property terms of use of user accepted terms of use ")
  void test_terms_of_use_v_o_builder() {
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertEquals("10", TermsOfUseVO.fromReference("10").getTermsOfUseUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("11", TermsOfUseVO.tryFromReference("11").getTermsOfUseUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("12", TermsOfUseVO.tryFromReference("12", fails).getTermsOfUseUid(),
        "The builder must store the reference value");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertThrows(ConstraintException.class, () -> TermsOfUseVO.tryFrom(null));
    Assertions.assertEquals(TenantTermsOfUseReference.of("one"),
        TermsOfUseVO.from(TenantTermsOfUseReference.of("one")).getTermsOfUse());
    Assertions.assertThrows(ConstraintException.class, () -> TermsOfUseVO.tryFrom(new Object() {}));
    Assertions.assertEquals("[" + TenantTermsOfUseReference.of("one") + "]",
        TermsOfUseVO.from(TenantTermsOfUseReference.of("one")).toString());
  }
}
